INSERT INTO `categories` (`id`, `name_ar`, `name_en`, `slug`, `description_ar`, `description_en`, `image`, `display_order`, `is_active`, `created_at`, `updated_at`, `parent_id`) VALUES (1, 'مواد غذائية', 'Food Products', 'food-products', 'أجود المواد الغذائية والتموينية الأساسية، أرز فاخر، زيوت، بقوليات، مكرونة ومعلبات طازجة مطابقة لأعلى معايير سلامة الغذاء.', NULL, 'https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=800&q=80', 1, 1, '2026-11-19 08:11:32', '2026-11-19 08:11:32', NULL);
