INSERT INTO `products` (`id`, `category_id`, `name_ar`, `name_en`, `slug`, `sku`, `description_ar`, `description_en`, `regular_price`, `sale_price`, `stock_quantity`, `size`, `weight`, `fragrance_top`, `fragrance_heart`, `fragrance_base`, `is_featured`, `is_active`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (14, 3, 'مطهر ومعقم الأرضيات والأسطح برائحة اللافندر الفواحة - 3 لتر', 'Surface & Floor Disinfectant Lavender 3L', 'surface-floor-disinfectant-lavender-3l', 'ZN-CLN-003', 'منظف ومطهر أرضيات متعدد الأسطح بتركيبة فعالة توفر حماية صحية متكاملة لبيتك وتترك رائحة زكية ومنعشة تملأ أرجاء المنزل طوال اليوم.', NULL, 28, 22, 110, '3 لتر', '3000ml', 'يقضي على 99.9% من الجراثيم والبكتيريا', 'يمنح الأرضيات لمعاناً كريستالياً براقاً', 'خلاصة اللافندر المنعشة للملابس', 1, 1, NULL, NULL, '2026-11-19 08:11:35', '2026-11-19 08:11:35');
INSERT INTO `products` (`id`, `category_id`, `name_ar`, `name_en`, `slug`, `sku`, `description_ar`, `description_en`, `regular_price`, `sale_price`, `stock_quantity`, `size`, `weight`, `fragrance_top`, `fragrance_heart`, `fragrance_base`, `is_featured`, `is_active`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (15, 3, 'مبيض ومعقم أقمشة وأسطح متعدد الاستخدامات - جالون 3.78 لتر', 'Multi-Purpose Bleach & Disinfectant 3.78L', 'multi-purpose-bleach-3-78l', 'ZN-CLN-004', 'مبيض كلور متعدد الاستخدامات يزيل البقع الصعبة عن الملابس البيضاء ويضمن تعقيماً عميقاً للأسطح المنزلية والحمامات والمطابخ.', NULL, 17, 14, 130, '3.78 لتر', '3780ml', 'بياض ناصع وقوة تعقيم مثبتة', 'مطهر قوي للمراحيض والأحواض والمطابخ', 'عبوة جالون اقتصادية متينة', 0, 1, NULL, NULL, '2026-11-19 08:11:35', '2026-11-19 08:11:35');
INSERT INTO `products` (`id`, `category_id`, `name_ar`, `name_en`, `slug`, `sku`, `description_ar`, `description_en`, `regular_price`, `sale_price`, `stock_quantity`, `size`, `weight`, `fragrance_top`, `fragrance_heart`, `fragrance_base`, `is_featured`, `is_active`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (16, 4, 'مناديل وجه ناعمة ثلاثية الطبقات - عبوة توفيرية 10 علب × 200 منديل', 'Soft Facial Tissues 3-Ply 10 Packs x 200 Sheets', 'soft-facial-tissues-10pack-200sheets', 'ZN-ACC-001', 'مناديل ورقية فائقة النعومة من لب الشجر الطبيعي النقي، توفر لك ولعائلتك عناية لطيفة وامتصاصاً ممتازاً في كل الأوقات بعبوة توفيرية ممتازة.', NULL, 28, 22.5, 220, '10 علب × 200 منديل', '2000g', 'قطن طبيعي نقي 100% شديد النعومة', 'ثلاث طبقات ماصة ومتينة لا تتمزق بسهولة', 'مناسبة للاستخدام اليومي للبشرة الحساسة', 1, 1, NULL, NULL, '2026-11-19 08:11:35', '2026-11-19 08:11:35');
INSERT INTO `products` (`id`, `category_id`, `name_ar`, `name_en`, `slug`, `sku`, `description_ar`, `description_en`, `regular_price`, `sale_price`, `stock_quantity`, `size`, `weight`, `fragrance_top`, `fragrance_heart`, `fragrance_base`, `is_featured`, `is_active`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (17, 4, 'قصدير ألومنيوم فائق القوة للطهي والتغليف - 45 سم × 100 متر', 'Heavy Duty Aluminium Cooking Foil 45cm x 100m', 'heavy-duty-aluminium-foil-45cm-100m', 'ZN-ACC-002', 'رول قصدير ألومنيوم شديد التحمل بسماكة ممتازة يحمي اللحوم والأطعمة أثناء الخبز والشواء ويحافظ على الرطوبة والنكهة الطازجة.', NULL, 34, 27.5, 100, '45 سم × 100 م', '1200g', 'سماكة عالية مقاومة للتمزق والحرارة العالية', 'مثالي للشواء، تغليف الصواني، وحفظ الأطعمة', 'صحي وآمن للتلامس المباشر مع الأغذية', 1, 1, NULL, NULL, '2026-11-19 08:11:36', '2026-11-19 08:11:36');
INSERT INTO `products` (`id`, `category_id`, `name_ar`, `name_en`, `slug`, `sku`, `description_ar`, `description_en`, `regular_price`, `sale_price`, `stock_quantity`, `size`, `weight`, `fragrance_top`, `fragrance_heart`, `fragrance_base`, `is_featured`, `is_active`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (18, 4, 'رول مناديل مطبخ ماصة متعددة الاستخدامات - شدة 6 رول جامبو', 'Jumbo Kitchen Towels 6-Roll Pack', 'jumbo-kitchen-towels-6roll', 'ZN-ACC-003', 'مناديل مطبخ فائقة الامتصاص مخصصة لتجفيف الأطعمة وتصفية الزيوت وتنظيف أسطح الطهي والزجاج بكفاءة عالية وبدون ترك شوائب.', NULL, 20, 16, 160, '6 رول جامبو', '1100g', 'قدرة امتصاص فائقة للزيوت والسوائل', 'ملمس متماسك لا يترك وبر على الزجاج والصحون', 'اقتصادي وعملي لجميع مهام المطبخ', 0, 1, NULL, NULL, '2026-11-19 08:11:36', '2026-11-19 08:11:36');
INSERT INTO `products` (`id`, `category_id`, `name_ar`, `name_en`, `slug`, `sku`, `description_ar`, `description_en`, `regular_price`, `sale_price`, `stock_quantity`, `size`, `weight`, `fragrance_top`, `fragrance_heart`, `fragrance_base`, `is_featured`, `is_active`, `seo_title`, `seo_description`, `created_at`, `updated_at`) VALUES (19, 4, 'أكياس نفايات متينة برباط سحب محكم سعة 50 لتر - شدة 30 كيس', 'Heavy Duty Drawstring Trash Bags 50L 30ct', 'heavy-duty-trash-bags-50l-30ct', 'ZN-ACC-004', 'أكياس نفايات منزلية قوية التحمل تمنع تسرب السوائل ومزودة بشريط سحب علوي لسهولة الإغلاق والحمل دون ملامسة المحتويات.', NULL, 16, 12.5, 170, '30 كيس × 50 لتر', '800g', 'بلاستيك مرن عالي الكثافة مانع للتسريب', 'رباط سحب سهل للإغلاق والحمل المحكم', 'رائحة خفيفة مانعة للروائح غير المرغوبة', 0, 1, NULL, NULL, '2026-11-19 08:11:36', '2026-11-19 08:11:36');
